package monitoring.agent

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import java.nio.charset.{Charset, StandardCharsets}
import java.util.Base64
import java.io.{File, FileWriter, BufferedWriter}
import scala.collection.concurrent.TrieMap

object EncodingConfig {
  val SAFE_CHARSET: Charset = StandardCharsets.UTF_8
  val LOG_DIR: String = "/var/log/agent/"
  val MAX_FIELD_LENGTH: Int = 512
  val ALLOWED_CHARS_PATTERN = """^[\p{L}\p{N}\s._\-/=+@:,;()\[\]{}]+$""".r
}

case class LogEntry(timestamp: Long, source: String, message: String, metadata: Map[String, String])

trait EncodingNormalizer {
  def normalize(input: String): String
  def isValidEncoding(bytes: Array[Byte]): Boolean
}

class Utf8Normalizer extends EncodingNormalizer {
  import java.text.Normalizer

  override def normalize(input: String): String = {
    val nfcNormalized = Normalizer.normalize(input, Normalizer.Form.NFC)
    nfcNormalized
  }

  override def isValidEncoding(bytes: Array[Byte]): Boolean = {
    val decoder = EncodingConfig.SAFE_CHARSET.newDecoder()
    try {
      decoder.decode(java.nio.ByteBuffer.wrap(bytes))
      true
    } catch {
      case _: Exception => false
    }
  }
}

class FieldSanitizer(normalizer: EncodingNormalizer) {

  def sanitizeField(field: String): Either[String, String] = {
    if (field == null || field.isEmpty) return Right("")

    val normalized = normalizer.normalize(field)

    if (normalized.length > EncodingConfig.MAX_FIELD_LENGTH) {
      Left(s"Field exceeds max length: ${normalized.length}")
    } else {
      Right(normalized)
    }
  }

  def sanitizeMetadata(metadata: Map[String, String]): Map[String, String] = {
    metadata.map { case (k, v) =>
      val safeKey = sanitizeField(k).getOrElse("invalid_key")
      val safeValue = sanitizeField(v).getOrElse("")
      (safeKey, safeValue)
    }
  }
}

class PathValidator {
  private val traversalPatterns = List("..", "~", "${", "%2e", "%2f")

  def validateLogPath(filename: String): Either[String, String] = {
    val decoded = java.net.URLDecoder.decode(filename, "UTF-8")

    if (traversalPatterns.exists(p => decoded.toLowerCase.contains(p))) {
      Left(s"Path traversal detected in: $filename")
    } else {
      val fullPath = EncodingConfig.LOG_DIR + decoded
      val canonical = new File(fullPath).getCanonicalPath
      if (canonical.startsWith(EncodingConfig.LOG_DIR)) {
        Right(canonical)
      } else {
        Left(s"Path escapes log directory: $canonical")
      }
    }
  }
}

class AsyncLogWriter(sanitizer: FieldSanitizer, pathValidator: PathValidator) {
  private val writeBuffer = TrieMap[String, List[String]]()
  private val encodingCache = TrieMap[Int, Array[Byte]]()

  def processEntry(entry: LogEntry): Future[Either[String, Unit]] = Future {
    val sanitizedMeta = sanitizer.sanitizeMetadata(entry.metadata)
    val sanitizedMsg = sanitizer.sanitizeField(entry.message)

    sanitizedMsg match {
      case Right(msg) =>
        val logLine = formatLogLine(entry.timestamp, entry.source, msg, sanitizedMeta)
        writeToBuffer(entry.source, logLine)
      case Left(err) =>
        Left(s"Message sanitization failed: $err")
    }
  }

  private def formatLogLine(ts: Long, source: String, msg: String, meta: Map[String, String]): Either[String, Unit] = {
    val metaStr = meta.map { case (k, v) => s"$k=$v" }.mkString("; ")
    val line = s"[$ts] [$source] $msg | $metaStr"

    val encodedBytes = line.getBytes(EncodingConfig.SAFE_CHARSET)
    val cacheKey = line.hashCode
    encodingCache.put(cacheKey, encodedBytes)

    Right(())
  }

  private def writeToBuffer(source: String, result: Either[String, Unit]): Either[String, Unit] = {
    result match {
      case Right(_) =>
        val existing = writeBuffer.getOrElse(source, List.empty)
        writeBuffer.put(source, existing :+ s"entry_${System.nanoTime()}")
        Right(())
      case Left(err) => Left(err)
    }
  }

  def flushBuffer(targetFile: String): Future[Either[String, Int]] = Future {
    pathValidator.validateLogPath(targetFile) match {
      case Right(validPath) =>
        val allEntries = writeBuffer.values.flatten.toList
        writeBuffer.clear()
        Right(allEntries.size)
      case Left(err) => Left(err)
    }
  }
}

class MonitoringAgent {
  private val normalizer = new Utf8Normalizer()
  private val sanitizer = new FieldSanitizer(normalizer)
  private val pathValidator = new PathValidator()
  private val logWriter = new AsyncLogWriter(sanitizer, pathValidator)

  def ingestLog(rawSource: String, rawMessage: String, rawMeta: Map[String, String]): Future[Either[String, Unit]] = {
    val sourceBytes = rawSource.getBytes(StandardCharsets.UTF_8)

    if (!normalizer.isValidEncoding(sourceBytes)) {
      Future.successful(Left("Invalid encoding in source"))
    } else {
      val entry = LogEntry(
        timestamp = System.currentTimeMillis(),
        source = rawSource,
        message = rawMessage,
        metadata = rawMeta
      )
      logWriter.processEntry(entry)
    }
  }

  def exportLogs(filename: String): Future[Either[String, Int]] = {
    logWriter.flushBuffer(filename)
  }
}

object AgentApp extends App {
  val agent = new MonitoringAgent()

  val testMeta = Map(
    "host" -> "server-01",
    "level" -> "INFO",
    "correlation_id" -> "abc-123"
  )

  agent.ingestLog("app-service", "Health check passed", testMeta)
  agent.exportLogs("audit.log")
}
